from .node import Node
from .exceptions import TstmProcessNotExist


class Tstm(Node):

    def __init__(self, config, executor, **kwargs):
        super().__init__(config, executor, **kwargs)

    def get_tstm_log(self, expect_regex, timeout):
        return self.read_persist_channel(expect_regex, timeout)

    def check_tstm_status(self):
        res = self._executor.execute("ps -ef | grep tstm | grep -v 'grep'")
        if not res.strip():
            raise TstmProcessNotExist
